#include "ksSysExActionTask.h"
#include <vector>
#include <tuple>
#include <iostream>
#include <stdexcept>
using T=ks::SysExActionTask;using K=T::Kind;using S=T::Stage;using C=T::Child;using Event=std::pair<S,unsigned>;
void check(bool v,const char* why){if(!v)throw std::runtime_error(why);}
int main(){try{uint64_t cases=0;auto verify=[&](K kind,unsigned mode,unsigned bank,unsigned program,unsigned slot,unsigned count,bool active,unsigned latency){
 constexpr uint32_t source=0xfffffff0u,record=0xffa16040u;T t(kind,record,source,uint16_t(count),uint8_t(program));std::vector<C>children;std::vector<Event>writes;std::vector<unsigned>serial;unsigned reads=0,loops=0;while(!t.complete()&&!t.handoff()){
  check(++loops<1000000,"Pure SysEx action stalled");if(t.awaitingChild()){children.push_back(t.child());switch(t.child()){case C::Active:check(t.resumeActive(active),"Active rejected");break;case C::Resolve:check(t.resumeResolve(record),"Resolve rejected");break;case C::UiText:check(t.resumeUi(record,uint8_t(program+1)),"UI text rejected");break;case C::UiByte:check(t.bank()==uint8_t(bank+48),"Bank digit differs");check(t.resumeUi(record,uint8_t(program+2)),"UI byte rejected");break;case C::UiNumber:check(t.program()==uint8_t(program+2),"Fresh program reply differs");check(t.resumeChild(),"UI number rejected");break;case C::Serial:serial.push_back(t.byte());check(t.resumeChild(),"Serial rejected");break;case C::Send:check(t.source()==0x16044&&t.remaining()==12,"Header send request differs");check(t.resumeChild(),"Send rejected");break;default:check(t.resumeChild(),"Action child rejected");break;}continue;}
  auto read=[&](S s)->unsigned{++reads;switch(s){case S::PatchReadMode:case S::MultiReadMode:return mode;case S::PatchBankReadBank:check(t.record()==record,"Record reply lost");return bank;case S::PatchBankReadProgram:case S::MultiBankReadProgram:return program;case S::ResolveReadSlot:return slot;case S::ResolveReadFallback:return bank;case S::PatchReportReadBank:case S::MultiReportReadBank:check(t.record()==record,"UI record reply lost");return bank;case S::HeaderRead:return uint8_t(t.index()*37+bank);case S::SendRead:return uint8_t(t.source()*37+bank);default:throw std::runtime_error("Unexpected action read");}};auto write=[&](S s,unsigned v){writes.emplace_back(s,v);};auto timing=[&](S){return latency;};const auto cost=t.nextClocks(t.publication()?latency:3);check(cost>0,"Action deadline stalled");const auto before=reads+writes.size();check(!t.advanceBefore(cost-1,read,write,timing)&&reads+writes.size()==before,"Early action access");check(t.advanceBefore(cost,read,write,timing)==cost,"Action deadline differs");}
 std::vector<C>ec;std::vector<Event>ew;std::vector<unsigned>es;bool handed=false;T::Route route=T::Route::PatchMessage;switch(kind){case K::Patch:if(!mode){ec={C::ApplyPatch,C::Active};if(active)ec.push_back(C::Refresh);handed=true;}break;case K::Multi:if(mode){ec={C::ApplyMulti,C::Active};if(active)ec.push_back(C::Refresh);handed=true;route=T::Route::MultiMessage;}break;case K::Global:ec={C::ApplyGlobal};handed=true;route=T::Route::GlobalMessage;break;case K::PatchBank:ec={C::Resolve};if(bank>=1&&bank<=8&&program<(bank<=4?100u:50u)){ec.push_back(C::ReportPatch);ec.push_back(C::CommitPatch);}break;case K::MultiBank:ew.emplace_back(S::MultiBankPublishBank,1);if(program<100)ec={C::ReportMulti,C::CommitMulti};check(t.record()==0x16040,"Multi record binding differs");break;case K::Resolve:if(!slot)ew.emplace_back(S::ResolvePublishFallback,bank);check(t.record()==0x16040,"Resolved record binding differs");break;case K::PatchReport:case K::MultiReport:ec={C::UiText,C::UiByte,C::UiNumber};break;case K::Header:for(unsigned i=0;i<12;++i)ew.emplace_back(S::HeaderPublish,uint8_t(i*37+bank));break;case K::Send:{const unsigned n=count?count:65536;for(unsigned i=0;i<n;++i){ec.push_back(C::Serial);es.push_back(uint8_t(uint32_t(source+i)*37+bank)&127);}check(t.source()==uint32_t(source+n)&&t.remaining()==0,"Send pointer/count wrap differs");break;}case K::SendHeader:ec={C::Serial,C::Send};es={240};break;}
 check(writes==ew,"Action publications differ");check(children==ec,"Action child ordering differs");check(serial==es,"Serial mask/delivery differs");check(t.handoff()==handed&&(!handed||t.route()==route),"Action notification route differs");++cases;
 };
 for(unsigned latency:{0u,3u}){
  for(unsigned bank=0;bank<256;++bank)for(unsigned program=0;program<256;++program)verify(K::PatchBank,0,bank,program,0,12,false,latency);
  for(unsigned slot=0;slot<256;++slot)for(unsigned bank=0;bank<256;++bank)verify(K::Resolve,0,bank,0,slot,12,false,latency);
  for(unsigned bank=0;bank<256;++bank)for(unsigned program=0;program<256;++program)for(auto k:{K::PatchReport,K::MultiReport})verify(k,0,bank,program,0,12,false,latency);
  for(unsigned mode=0;mode<256;++mode)for(bool active:{false,true})for(auto k:{K::Patch,K::Multi,K::Global,K::MultiBank,K::Header})verify(k,mode,7,mode,0,12,active,latency);
  for(unsigned count:{0u,1u,2u,12u,127u,255u,256u,1024u,65535u})verify(K::Send,0,7,0,0,count,false,latency);
  verify(K::SendHeader,0,7,0,0,12,false,latency);
 }
 std::cout<<"PASS: "<<cases<<" pure SysEx apply/bank/report/header/send tasks, independent validation/request oracle, live UI replies, full byte metadata,16-bit send count and pointer wrap/masking, early deadlines\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
